import React, { useEffect, useState } from 'react';
import API from '../api';

export default function News() {
  const [news, setNews] = useState([]);
  const [loading, setLoading] = useState(true);
  const [selected, setSelected] = useState(null);

  useEffect(() => {
    API.get('/news').then((r) => setNews(r.data)).finally(() => setLoading(false));
  }, []);

  if (loading) return <div style={{ textAlign: 'center', padding: 80, color: '#a3a3a3' }}>Loading...</div>;

  return (
    <div style={{ maxWidth: 1000, margin: '0 auto', padding: '60px 24px' }}>
      <h1 style={{ fontSize: 40, fontWeight: 900, marginBottom: 8 }}>News</h1>
      <p style={{ color: '#a3a3a3', marginBottom: 40 }}>Latest updates and articles</p>

      <div style={{ display: 'flex', flexDirection: 'column', gap: 24 }}>
        {news.map((n) => (
          <div key={n.id} style={{ background: '#171717', border: '1px solid #262626', borderRadius: 20, overflow: 'hidden' }}>
            {n.images?.[0] && (
              <img src={n.images[0].url} alt={n.title} style={{ width: '100%', height: 240, objectFit: 'cover' }} />
            )}
            <div style={{ padding: 24 }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 12 }}>
                <span style={{ background: '#f9731620', color: '#f97316', padding: '4px 12px', borderRadius: 20, fontSize: 12, fontWeight: 600 }}>{n.category}</span>
                <span style={{ color: '#666', fontSize: 13 }}>{new Date(n.created_at || n.date).toLocaleDateString()}</span>
              </div>
              <h2 style={{ fontSize: 22, fontWeight: 800, marginBottom: 10, lineHeight: 1.3 }}>{n.title}</h2>
              <p style={{ color: '#a3a3a3', fontSize: 15, lineHeight: 1.7, marginBottom: 16 }}>
                {n.content.length > 180 ? n.content.slice(0, 180) + '...' : n.content}
              </p>
              <button onClick={() => setSelected(n)} style={{ background: '#f97316', color: '#000', border: 'none', padding: '10px 20px', borderRadius: 8, fontWeight: 700, fontSize: 14 }}>
                Read More →
              </button>
            </div>
          </div>
        ))}
        {news.length === 0 && <p style={{ color: '#a3a3a3', textAlign: 'center' }}>No articles yet.</p>}
      </div>

      {/* Modal */}
      {selected && (
        <div onClick={() => setSelected(null)} style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.85)', zIndex: 9999, display: 'flex', alignItems: 'flex-end', justifyContent: 'center' }}>
          <div onClick={(e) => e.stopPropagation()} style={{ background: '#111', borderRadius: '20px 20px 0 0', width: '100%', maxWidth: 700, maxHeight: '90vh', overflowY: 'auto', padding: 32 }}>
            <button onClick={() => setSelected(null)} style={{ float: 'right', background: 'none', border: 'none', color: '#fff', fontSize: 24, cursor: 'pointer' }}>✕</button>
            <span style={{ background: '#f9731620', color: '#f97316', padding: '4px 12px', borderRadius: 20, fontSize: 12, fontWeight: 600 }}>{selected.category}</span>
            <h2 style={{ fontSize: 26, fontWeight: 900, margin: '16px 0 8px', lineHeight: 1.3 }}>{selected.title}</h2>
            <p style={{ color: '#666', fontSize: 13, marginBottom: 20 }}>{new Date(selected.created_at || selected.date).toLocaleDateString()}</p>
            {selected.images?.length > 0 && (
              <div style={{ display: 'flex', gap: 10, overflowX: 'auto', marginBottom: 20 }}>
                {selected.images.map((img) => (
                  <img key={img.id} src={img.url} alt="" style={{ height: 180, borderRadius: 10, objectFit: 'cover', flexShrink: 0 }} />
                ))}
              </div>
            )}
            <p style={{ color: '#d4d4d4', fontSize: 16, lineHeight: 1.8 }}>{selected.content}</p>
          </div>
        </div>
      )}
    </div>
  );
}
